<?php
/** Slice 6 — the count sheet's lines (counts.md "Proof": Lines): a case + loose, a weighed bottle, zero, skip, a line found on the shelf, idempotence, the blind rule. Leaves an open count with every line entered, for the review. */
require __DIR__ . '/lib.php';
$w = count_world();
$bea = person(28); $dana = person(30); $ann = person(29);
$sid = (int) one("SELECT id FROM count_sheets WHERE name = 'Full house' AND scope_id = :s", ['s' => DOWNTOWN]);
$c1 = (int) one("SELECT id FROM containers WHERE name = '750 ml bottle'"); $c2 = (int) one("SELECT id FROM containers WHERE name = '1 L bottle'");
reset_counts();
[$cid, ] = start_count_as($bea, ['sheet' => $sid]);
$L = ['flour' => line_of($cid, $w['flour']), 'egg' => line_of($cid, $w['egg']), 'gin' => line_of($cid, $w['gin']), 'lime' => line_of($cid, $w['lime']), 'oil' => line_of($cid, $w['oil']), 'chicken' => line_of($cid, $w['chicken'])];
$sets = static fn (array $f): array => ['count_line' => $f[0]] + $f[1];

echo "1. The sheet, one area at a time\n";
$h = page($bea, "/counts/$cid");
ok($h['code'] === 200 && has($h, 'data-screen="count-view"') && has($h, 'data-entity="inventory_count"') && has($h, 'id="count-area-pager"') && has($h, 'id="count-progress"') && has($h, 'id="count-lines"'), 'the count sheet: the screen stamps, the area pager, the progress, the lines');
ok(has($h, 'id="count-area-name">SMOKE Walk-in<') && has($h, 'Area 1 of 4') && has($h, 'id="count-line-' . $L['egg'] . '"') && !has($h, 'id="count-line-' . $L['flour'] . '"'), 'it opens at the first area with work to do (the Walk-in), and shows that area\'s lines only');
ok(has($h, 'id="count-progress-done">0<') && has($h, 'id="count-progress-total">6<') && has($h, 'id="count-review-btn"') && preg_match('/id="count-review-btn"[^>]*disabled/', $h['body']) === 1 && has($h, '6 lines are still pending'), '0 of 6 lines; Review is disabled and says why');
ok(has($h, 'id="count-line-' . $L['egg'] . '-whole"') && has($h, 'id="count-line-' . $L['egg'] . '-loose"') && has($h, 'id="count-line-' . $L['egg'] . '-zero"') && has($h, 'id="count-line-' . $L['egg'] . '-skip"') && has($h, 'id="count-line-' . $L['egg'] . '-state"') && has($h, 'id="count-line-' . $L['egg'] . '-save"'), 'a line: whole and loose inputs, 0 and Skip, the state chip, and the Save button the no-JavaScript path posts');
ok(!has($h, 'id="count-line-' . $L['egg'] . '-gross"'), 'no scale input for eggs');
$hd = page($dana, '/counts/' . $cid . '?area=' . $w['dry']);
ok(has($hd, 'id="count-line-' . $L['flour'] . '"') && has($hd, '<option value="lb"'), 'another area by ?area=; the loose unit offers the pound');
$hb = page($bea, '/counts/' . $cid . '?area=' . $w['bar']);
ok(has($hb, 'id="count-line-' . $L['gin'] . '-gross"') && has($hb, 'id="count-line-' . $L['gin'] . '-container"') && !has($hb, 'id="count-line-' . $L['lime'] . '-gross"'), 'the Bar: the scale input and the choice of bottle for gin (it has two), none for limes');
ok(has($hb, 'id="count-area-prev"') && has($hb, 'id="count-area-next"') && preg_match('#href="/counts/' . $cid . '\?area=' . $w['dry'] . '"[^>]*id="count-area-prev"#', $hb['body']) === 1, 'prev and next link to the neighbouring areas in walk order');
ok(page($ann, "/counts/$cid")['code'] === 403, 'Ann (Viewer) cannot open the sheet to fill: 403');

echo "2. The blind rule\n";
ok(!has($hd, 'id="count-blind-note"'), 'Dana (a Chef) is not told the count is blind to her');
$hd = page($dana, '/counts/' . $cid . '?area=' . $w['dry']);
ok(has($hd, 'id="count-line-' . $L['flour'] . '-book"') && has(['body' => preg_replace('/\s+/', ' ', $hd['body'])], 'book 6 bag50'), 'Dana (counts.approve) sees "book 6 bag50" on the open blind count');
$hb2 = page($bea, '/counts/' . $cid . '?area=' . $w['dry']);
ok(!has($hb2, 'id="count-line-' . $L['flour'] . '-book"') && !str_contains($hb2['body'], '136077') && has($hb2, 'id="count-blind-note"'), 'Bea (the counter) gets no book figure anywhere in the page, and the page says it is blind');
$j = get_json($bea, '/counts/' . $cid . '?area=' . $w['dry']);
$jl = $j['json']['data']['lines'][0] ?? [];
ok(!array_key_exists('system_qty_base', $jl) && ($jl['book_hidden'] ?? false) === true && !str_contains($j['body'], '136077'), 'JSON for Bea: book_hidden, no system_qty_base, nowhere in the body');
$j = get_json($dana, '/counts/' . $cid . '?area=' . $w['dry']);
ok(near($j['json']['data']['lines'][0]['system_qty_base'] ?? null, 136077.711, 0.001), 'JSON for Dana: system_qty_base 136 077.711 g');

echo "3. Entering quantities\n";
$before = last_activity_id();
$r = post($bea, '/counts/line.php', ['count_line' => $L['flour'], 'whole' => '6', 'whole_unit' => 'bag50', 'loose' => '5', 'loose_unit' => 'lb']);
$ln = cline($L['flour']);
ok($r['code'] === 302 && preg_match('#^/counts/' . $cid . '\?area=' . $w['dry'] . '\#count-line-' . $L['flour'] . '$#', $r['location']) === 1, 'a form post (no JavaScript) lands back on the area at the line');
ok(near($ln['counted_qty_base'], 6 * 22679.6185 + 5 * 453.59237, 0.001) && $ln['state'] === 'counted' && (int) $ln['counted_by'] === 28 && count(json_decode($ln['entries'], true)) === 2, '6 bags + 5 lb of flour = 138 345.6729 g, counted by Bea, the entries kept as sent');
$a = activity('count.line_set', $before);
$af = json_decode($a[0]['after'] ?? '{}', true);
ok(count($a) === 1 && (int) $a[0]['ingredient_id'] === $w['flour'] && (int) $a[0]['count_id'] === $cid && (int) $a[0]['scope_id'] === DOWNTOWN && count($af['entries']) === 2 && near($af['counted_qty_base'], 138345.6729, 0.001), 'count.line_set logged with ingredient_id, count_id, scope_id and the entries as sent');
$r = post($bea, '/counts/line.php', ['count_line' => $L['flour'], 'whole' => '6', 'whole_unit' => 'bag50', 'loose' => '5', 'loose_unit' => 'lb']);
$ln2 = cline($L['flour']);
ok($r['code'] === 302 && $ln2['counted_qty_base'] === $ln['counted_qty_base'] && $ln2['entries'] === $ln['entries'] && $ln2['state'] === 'counted', 'the same entries twice leave the line as it was (idempotent)');
$r = post($bea, '/counts/line.php', ['count_line' => $L['egg'], 'whole' => '10', 'whole_unit' => 'flat', 'loose' => '7', 'loose_unit' => 'each'], ['HX-Request: true']);
ok($r['code'] === 200 && near(cline($L['egg'])['counted_qty_base'], 307, 0.0001), '10 flats + 7 eggs = 307 each');
ok(has($r, 'id="count-line-' . $L['egg'] . '"') && has($r, 'data-state="counted"') && !has($r, 'id="count-line-' . $L['egg'] . '-book"') && !str_contains($r['body'], '<html'), 'the Pattern C answer is the line\'s partial alone — no book figure on a blind count');
preg_match('/^X-Count-Progress: (.+)$/mi', $r['headers'], $m);
$pg = json_decode(trim($m[1] ?? '{}'), true);
ok(($pg['lines'] ?? 0) === 6 && ($pg['done'] ?? 0) === 2 && ($pg['pending'] ?? 0) === 4 && ($pg['area']['done'] ?? -1) === 1, '…with the progress in a header (2 of 6 done, 1 of 2 in the Walk-in) for the script to move the bar');
$r = post($bea, '/counts/line.php', ['count_line' => $L['gin'], 'whole' => '11', 'whole_unit' => 'bottle', 'gross_weight_g' => '900', 'container' => $c1]);
ok($r['code'] === 302 && near(cline($L['gin'])['counted_qty_base'], 8625, 0.001) && (int) cline($L['gin'])['container_id'] === $c1 && near(cline($L['gin'])['gross_weight_g'], 900, 0.001), '11 bottles + a 900 g weighed bottle (with its pourer) = 8 625 ml; the container and the weight kept');
$r = post($bea, '/counts/line.php', ['count_line' => $L['gin'], 'gross_weight_g' => '900']);
ok($r['code'] === 302 && near(cline($L['gin'])['counted_qty_base'], 375, 0.001) && count(json_decode(cline($L['gin'])['entries'], true)) === 0, 'a weight alone reads the default bottle: 375 ml (the earlier entries are replaced, as sent)');
post($bea, '/counts/line.php', ['count_line' => $L['gin'], 'whole' => '11', 'whole_unit' => 'bottle', 'gross_weight_g' => '900', 'container' => $c1]);

echo "4. Zero, skip, and what the database refuses\n";
$r = post($bea, '/counts/line.php', ['count_line' => $L['lime'], 'state' => 'zero']);
ok($r['code'] === 302 && cline($L['lime'])['state'] === 'zero' && near(cline($L['lime'])['counted_qty_base'], 0, 0.0001), '0: the limes are none on the shelf (300 on the book)');
$r = post($bea, '/counts/line.php', ['count_line' => $L['chicken'], 'state' => 'skipped']);
ok($r['code'] === 302 && cline($L['chicken'])['state'] === 'skipped' && cline($L['chicken'])['counted_qty_base'] === null, 'Skip: the chicken is not counted (no figure)');
$r = post($bea, '/counts/line.php', ['count_line' => $L['oil'], 'state' => 'skipped']);
ok(cline($L['oil'])['state'] === 'skipped', '…and the oil in the Walk-in');
$r = post($bea, '/counts/line.php', ['count_line' => $L['lime'], 'note' => 'nothing']);
ok($r['code'] === 422 && says($r, 'A counted line carries entries or a weight'), 'no entries and no weight: "A counted line carries entries or a weight"');
$r = post($bea, '/counts/line.php', ['count_line' => $L['lime'], 'gross_weight_g' => '500']);
ok($r['code'] === 422 && says($r, 'No container is known for this ingredient'), 'a weight on limes: "No container is known for this ingredient — a weight cannot be read"');
$r = post($bea, '/counts/line.php', ['count_line' => $L['egg'], 'whole' => '2', 'whole_unit' => 'zzz']);
ok($r['code'] === 422 && says($r, 'No unit zzz for SMOKE Eggs') && near(cline($L['egg'])['counted_qty_base'], 307, 0.0001), 'a unit the ingredient cannot convert: the database\'s sentence, and the line is unchanged');
$r = post($bea, '/counts/line.php', ['count_line' => $L['egg'], 'whole' => '-3', 'whole_unit' => 'flat']);
ok($r['code'] === 422 && says($r, 'zero or more'), 'a negative quantity: refused in words');
$r = post($bea, '/counts/line.php', ['count_line' => $L['egg'], 'entries' => 'not json']);
ok($r['code'] === 422 && says($r, 'JSON list'), 'entries that are not a JSON list: refused in words');
$r = post($bea, '/counts/line.php', ['count_line' => $L['flour'], 'gross_weight_g' => '100', 'container' => $c1]);
ok($r['code'] === 422 && says($r, 'not one of this ingredient'), 'another ingredient\'s bottle: refused in words');
$r = post($bea, '/counts/line.php', ['count_line' => 999999, 'state' => 'zero']);
ok($r['code'] === 404, 'a line that is not here: 404');
$r = post($ann, '/counts/line.php', ['count_line' => $L['egg'], 'state' => 'zero']);
ok($r['code'] === 403 && near(cline($L['egg'])['counted_qty_base'], 307, 0.0001), 'Ann cannot enter a count: 403');

echo "5. A line found on the shelf\n";
$before = last_activity_id();
$r = post($bea, '/counts/line-add.php', ['count' => $cid, 'area' => $w['dry'], 'ingredient' => $w['oil'], 'qty' => '500', 'unit' => 'ml']);
$found = line_of($cid, $w['oil'], $w['dry']);
$fl = cline($found);
ok($r['code'] === 302 && $found > 0 && near($fl['counted_qty_base'], 500, 0.001) && $fl['state'] === 'counted' && near($fl['system_qty_base'], 0, 0.0001), 'olive oil found in the Dry store: 500 ml counted, the book figure there 0');
$a = activity('count.line_add', $before);
ok(count($a) === 1 && (int) $a[0]['ingredient_id'] === $w['oil'] && (int) $a[0]['count_id'] === $cid, 'count.line_add logged with ingredient_id and count_id');
$r = post($bea, '/counts/line-add.php', ['count' => $cid, 'area' => $w['dry'], 'ingredient' => $w['oil'], 'qty' => '1']);
ok($r['code'] === 422 && says($r, 'already on this count in that area'), 'the same ingredient twice in an area: refused in words');
$r = post($bea, '/counts/line-add.php', ['count' => $cid, 'area' => $w['awalkin'], 'ingredient' => $w['oil']]);
ok($r['code'] === 422 && says($r, 'storage area of the site'), 'an area of another site: refused in words');
$r = post($bea, '/counts/line-add.php', ['count' => $cid, 'area' => $w['dry'], 'ingredient' => 'nothing like it']);
ok($r['code'] === 422 && says($r, 'not here'), 'an ingredient that is not here: refused in words');
$h = page($bea, '/counts/' . $cid . '?area=' . $w['dry']);
ok(has($h, 'id="count-add-line-form"') && has($h, 'id="count-line-' . $found . '"') && has($h, 'id="count-progress-done">7<') && has($h, 'id="count-progress-total">7<'), 'the Found-on-the-shelf form is on the page; the new line is there; the progress counts it (7 of 7)');

echo "6. Everything entered\n";
$h = page($bea, "/counts/$cid");
ok((int) one("SELECT count(*) FROM inventory_count_lines WHERE count_id = :c AND state = 'pending'", ['c' => $cid]) === 0 && has($h, 'id="count-progress-done">7<') && !preg_match('/id="count-review-btn"[^>]*disabled/', $h['body']) && !has($h, 'id="count-pending-note"'), 'no line pending: 7 of 7 and Review is enabled');
finish();
